  const currentBlocks=key=>{if(settings.document?.sections?.[key])return settings.document.sections[key];const fields={briefing:'briefing',highlights:'highlights',children:'children_policy',payment:'payment_terms',cancellation:'cancellation_policy',notes:'important_notes'};return plainBlocks(key==='included'?v.included_text:key==='excluded'?v.excluded_text:key==='terms'?v.terms_text:settings[fields[key]]||'');};
  const changed=()=>{dirty=true;editRevision++;saveState='Unsaved changes';notice(saveState);const el=host.querySelector('[data-save-state]');if(el)el.textContent=saveState;if(edit&&saveTimer)clearTimeout(saveTimer);if(edit)saveTimer=setTimeout(()=>save(true),900);};
  const readDocument=()=>{if(view!=='document'||!edit)return;const d=doc();const title=host.querySelector('[data-doc-title]');if(title)d.title=title.textContent.trim();host.querySelectorAll('[data-rich-section]').forEach(el=>d.sections[el.dataset.richSection]=readBlocks(el));host.querySelectorAll('[data-rich-day]').forEach(el=>{d.days[el.dataset.richDay]=readBlocks(el);const day=days.find(x=>x.day_key===el.dataset.richDay);if(day)day.description=blockText(d.days[el.dataset.richDay]);});host.querySelectorAll('[data-day-field]').forEach(el=>{const day=days.find(x=>x.day_key===el.dataset.key);if(day)day[el.dataset.dayField]=el.textContent.trim();});};
  const checkpoint=()=>{readDay();undo.push(clone({days,links,settings}));if(undo.length>40)undo.shift();redo=[];const b=host.querySelector("[data-undo]");if(b)b.disabled=false;};
  const historyMove=(from,to)=>{if(!from.length)return;readDay();to.push(clone({days,links,settings}));({days,links,settings}=from.pop());changed();draw();};
