  const readDay=()=>{if(view==='document'){readDocument();return;}const f=host.querySelector('[data-day-form]');if(!f||!edit||!days[index])return;const b=formValues(f);for(const key of ['date','title','route','destination','activities','description','transport_mode','hotel','overnight','cruise','special_requests','public_notes','internal_notes','notes'])if(key in b)days[index][key]=b[key];days[index].guide_required=!!f.elements.guide_required.checked;days[index].overnight_type=b.overnight_type;days[index].meals=['B','L','D'].filter(x=>f.elements['meal_'+x].checked).join('/');if(settings.document?.days?.[days[index].day_key]&&blockText(settings.document.days[days[index].day_key])!==days[index].description)settings.document.days[days[index].day_key]=plainBlocks(days[index].description);};
  const save=async(automatic=false)=>{if(!edit)return false;if(saveTimer){clearTimeout(saveTimer);saveTimer=0;}if(busy){savePending=true;return false;}readDay();if(!dirty){saveState='Saved';const state=host.querySelector('[data-save-state]');if(state)state.textContent=saveState;return true;}const revision=editRevision,payload=clone({settings,days,links});busy=true;const buttons=[...host.querySelectorAll('button:not(:disabled)')];buttons.forEach(b=>b.disabled=true);saveState='Saving...';notice(saveState);const status=host.querySelector('[data-save-state]');if(status)status.textContent=saveState;try{const next=await api.request(base,{method:'PUT',body:{expected_revision:ctx.costing_revision,...payload}});ctx=next;if(editRevision===revision){days=next.days.map(d=>({...d}));links=next.links.map(l=>({...l}));settings=next.settings;dirty=false;saveState='Saved';notice('Saved.');if(status?.isConnected)status.textContent=saveState;}else{dirty=true;savePending=true;saveState='Saving newer changes...';notice(saveState);if(status?.isConnected)status.textContent=saveState;}return true;}catch(e){saveState='Save failed';notice(saveState+' · '+e.message);if(status?.isConnected)status.textContent=saveState;if(!automatic)toast(e.message,true);return false;}finally{busy=false;buttons.filter(b=>b.isConnected).forEach(b=>b.disabled=false);if(savePending||dirty&&editRevision!==revision){savePending=false;saveTimer=setTimeout(()=>save(true),120);}}};
  const captureRange=()=>{try{const sel=window.getSelection();if(sel?.rangeCount&&activeEditor?.contains(sel.anchorNode))activeRange=sel.getRangeAt(0).cloneRange();}catch{}};
