   if(action==='add'){let date='';const prior=days.at(-1)?.date;if(prior){const next=new Date(prior+'T00:00:00Z');if(!Number.isNaN(next.getTime())){next.setUTCDate(next.getUTCDate()+1);date=next.toISOString().slice(0,10);}}days.push({day_key:uuid(),date,title:'New day',description:'',meals:'',overnight:'',overnight_type:'UNREVIEWED'});index=days.length-1;}
