   host.querySelector('.page-head .actions').insertAdjacentHTML('afterbegin','<button class="btn" data-document-view>Document View</button><button class="btn primary" aria-pressed="true">Advanced View</button><button class="btn" data-open-media>Media</button>');const railElement=host.querySelector('.vs22-rail');railElement.classList.add('df-media-drawer');railElement.hidden=!mediaOpen;railElement.insertAdjacentHTML('afterbegin','<button class="btn" data-close-media>Close Media</button>');host.querySelector('.vs22-columns').classList.add('df-advanced-columns');
   host.querySelector('[data-document-view]').onclick=()=>toggle('document');host.querySelector('[data-open-media]').onclick=()=>{readDay();mediaOpen=true;draw();};host.querySelector('[data-close-media]').onclick=()=>{readDay();mediaOpen=false;draw();};
